function isVampire(n){
  n=Math.floor(Math.abs(+n));
  if(isNaN(n)||n<1) return {error:'请输入正整数'};
  var s=String(n), d=s.length;
  if(d%2!==0) return {value:false, isVampire:false, reason:'位数须为偶数'};
  if(d<4) return {value:false, isVampire:false, reason:'至少 4 位'};
  var k=d/2;
  var nd=s.split('').sort().join('');
  var lo=Math.pow(10,k-1), hi=Math.pow(10,k), found=null;
  for(var a=lo;a<hi;a++){
    if(n%a!==0) continue;
    var b=n/a;
    if(b<lo||b>=hi) continue;
    if((a%10===0)&&(b%10===0)) continue;
    var ab=(String(a)+String(b)).split('').sort().join('');
    if(ab===nd){ found=[a,b]; break; }
  }
  return {value:n, isVampire:!!found, fangs:found};
}
function vampireUpTo(limit){
  limit=Math.floor(+limit)||100000;
  if(limit<1000||limit>1e7) return {error:'上限须 1000–1e7'};
  var out=[], n;
  for(n=1000;n<=limit;n++){ var s=String(n); if(s.length%2!==0) continue; var r=isVampire(n); if(r.error||!r.isVampire) continue; out.push({n:n, fangs:r.fangs}); }
  return {value:out};
}
var EXPORTS={isVampire:isVampire, vampireUpTo:vampireUpTo};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.VampireForgePure = EXPORTS; }
